#!/usr/bin/env node
// Generate docs/eventual-consistency.md from the catalog JSONs:
//   specs/goals.json, specs/requirements.json, specs/assumptions.json,
//   specs/events.json
// These files are the source; edit them, then regenerate (just
// docs-eventual-consistency). The generated file is formatted
// afterwards by prettier via the recipe.
//
// Usage: gen-eventual-consistency-doc.mjs [specs-dir] [repo-root]
import { readFileSync, writeFileSync } from 'node:fs'
import { join, resolve } from 'node:path'

const [specsArg, rootArg] = process.argv.slice(2)
const specsDir = resolve(specsArg ?? '.')
const outPath = join(resolve(rootArg ?? '.'), 'docs', 'eventual-consistency.md')

function load(name) {
  return JSON.parse(readFileSync(join(specsDir, name), 'utf8'))
}

const goals = load('goals.json')
const requirements = load('requirements.json')
const assumptions = load('assumptions.json')
const events = load('events.json')

const lines = []
const add = (s = '') => lines.push(s)

add(`<!--Generated by scripts/gen-eventual-consistency-doc.mjs from`)
add(`specs/goals.json, specs/requirements.json, specs/assumptions.json and`)
add(`specs/events.json. Edit those files, then regenerate:`)
add(`just docs-eventual-consistency-->`)
add()
add('# Eventual consistency: goals, requirements, assumptions, events')
add()
add(`The catalogs below are the procedure's entry points. Goals are`)
add(`committed, queued, or dropped by human decision; requirements are`)
add(`derived from committed goals and stay open until their gate exists;`)
add(`assumptions are world-given and expensive (human review); events`)
add(`record the boundary between the world and the index pipeline with`)
add(`their desired settled state and known error cases. Formal`)
add(`grounding lives in \`specs/*.qnt\`, \`specs/assumptions.json\` and`)
add(`\`specs/scope.json\`; the closed-world audit is \`just spec-check\`.`)
add()

// ── Goals ──
add('## Goals')
add()
for (const g of goals.goals) {
  add(`### ${g.id}: ${g.title} (decision: ${g.decision})`)
  add()
  add(g.description)
  add()
  if (g.anchors.length > 0) {
    add('Anchors:')
    add()
    for (const a of g.anchors) add(`- ${a.kind}: \`${a.ref}\``)
    add()
  } else {
    add('Anchors: none — unanchored.')
    add()
  }
  if ((g.assumptions ?? []).length > 0) {
    add(`Holds under: ${g.assumptions.join(', ')}.`)
    add()
  }
  if (g.notes) {
    add(`Notes: ${g.notes}`)
    add()
  }
}

// ── Requirements ──
add('## Requirements')
add()
for (const r of requirements.requirements) {
  add(`### ${r.id}: ${r.title} (status: ${r.status})`)
  add()
  add(r.statement)
  add()
  add(`Derived from: ${r.derived_from.join(', ')}. Owner: ${r.owner}.`)
  add()
  add(`Gate: ${r.gate}`)
  add()
  if (r.notes) {
    add(`Notes: ${r.notes}`)
    add()
  }
}

// ── Assumptions ──
add('## Assumptions')
add()
for (const a of assumptions.assumptions) {
  add(`### ${a.id}: ${a.title} (status: ${a.status})`)
  add()
  add(`Owner: ${a.owner}.`)
  add()
  if (a.status_note) {
    add(`Status note: ${a.status_note}`)
    add()
  }
}

// ── Events ──
add('## Events')
add()
for (const ev of events.events) {
  add(`### ${ev.name} (${ev.status}, actor: ${ev.actor})`)
  add()
  add(ev.description)
  add()
  add(`Target: ${ev.target}. Code anchor: \`${ev.code_ref}\`.`)
  add()
  if (ev.preconditions.length > 0) {
    add(`Preconditions: ${ev.preconditions.join('; ')}.`)
    add()
  }
  if (ev.affected_state.length > 0) {
    add(`Touches: ${ev.affected_state.join(', ')}.`)
    add()
  }
  add('Effects (settled state assuming quiescence after the event):')
  add()
  for (const eff of ev.effects) add(`- ${eff}`)
  add()
  if (ev.faults.length > 0) {
    add('Faults:')
    add()
    for (const f of ev.faults) {
      add(`- ${f.fault} (${f.status}): ${f.consequence}`)
    }
    add()
  }
  if (ev.notes) {
    add(`Notes: ${ev.notes}`)
    add()
  }
}

writeFileSync(outPath, lines.join('\n') + '\n', 'utf8')
console.log(`gen-eventual-consistency-doc: wrote ${outPath}`)
